    a_intervals = [interval for interval in a if interval[0] < interval[1]]
    b_intervals = [interval for interval in b if interval[0] < interval[1]]

    # If a is empty, return empty list
    if not a_intervals:
        return []

    # Merge overlapping intervals in a
    a_merged = merge_intervals(a_intervals)

    # Merge overlapping intervals in b
    b_merged = merge_intervals(b_intervals)

    # Subtract b from a
    result = []
    for a_start, a_end in a_merged:
        current_ranges = [(a_start, a_end)]

        for b_start, b_end in b_merged:
            new_ranges = []
            for curr_start, curr_end in current_ranges:
                # No overlap
                if curr_end <= b_start or curr_start >= b_end:
                    new_ranges.append((curr_start, curr_end))
                else:
                    # There is overlap, split the current range
                    if curr_start < b_start:
                        new_ranges.append((curr_start, b_start))
                    if curr_end > b_end:
                        new_ranges.append((b_end, curr_end))
            current_ranges = new_ranges

        result.extend(current_ranges)

    # Sort and merge touching intervals
    if not result:
        return []

    result.sort()
    merged_result = [result[0]]
    for start, end in result[1:]:
        if merged_result[-1][1] == start:
            # Merge with previous interval
            merged_result[-1] = (merged_result[-1][0], end)
        else:
            merged_result.append((start, end))

    # Convert back to lists
    return [[s, e] for s, e in merged_result]


